const $ = (s)=>document.querySelector(s);

// --- Unicode helpers (very lightweight) ---
const COMBINING = /[\u0300-\u036f]/g;
const tonosMap = {
  'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
  'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
};
const circumflexComb = '\u0342'; // perispomeni
const acuteComb = '\u0301';
const graveComb = '\u0300';

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // remove combining marks; keep base letters
  return nfc(nfd(s).replace(COMBINING,''));
}

function stripAccentsOnly(s){
  // remove accent marks but keep breathings/diaeresis? For simplicity remove all combining.
  return stripDiacritics(s);
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code>=0x0370 && code<=0x03FF) || (code>=0x1F00 && code<=0x1FFF);
}

function lastIndexOfGreekVowelGroup(word){
  // returns array of vowel-group objects in order
  // vowel groups include diphthongs and single vowels.
  const w = stripDiacritics(word);
  const chars = Array.from(w);
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ','ΑΙ','ΕΙ','ΟΙ','ΥΙ','ΑΥ','ΕΥ','ΟΥ','ΗΥ','ΩΥ']);

  const groups=[];
  for(let i=0;i<chars.length;i++){
    const a=chars[i], b=chars[i+1];
    if(vowels.has(a)){
      const pair = b? (a+b):'';
      if(b && vowels.has(b) && diph.has(pair)){
        groups.push({text:pair, start:i, end:i+1, type:'diph'});
        i++;
      } else {
        groups.push({text:a, start:i, end:i, type:'vowel'});
      }
    }
  }
  return groups;
}

function endsWithSos(word){
  const w = stripDiacritics(word).toLowerCase();
  return w.endsWith('σος');
}

function applyAcuteToLastVowel(word){
  // naive: add acute to last vowel letter (not diphthong-aware)
  const base = nfd(word);
  const chars = Array.from(base);
  // find last Greek vowel base char
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  for(let i=chars.length-1;i>=0;i--){
    const ch = chars[i];
    if(vowels.has(ch)){
      // insert combining acute after this char, but before any existing combining marks following it
      let j=i+1;
      while(j<chars.length && /[\u0300-\u036f]/.test(chars[j])) j++;
      chars.splice(j,0,acuteComb);
      return nfc(chars.join(''));
    }
  }
  return word;
}

function applyAcuteToPenultVowel(word){
  const groups = lastIndexOfGreekVowelGroup(word);
  if(groups.length<2) return applyAcuteToLastVowel(word);
  const pen = groups[groups.length-2];
  // apply acute to first char of the penult group in original string positions (approx)
  const base = nfd(word);
  const chars = Array.from(base);
  // map from stripped positions to NFD positions is messy; we approximate by stripping first.
  // So we re-accent a stripped version instead.
  const stripped = stripAccentsOnly(word);
  const strippedNFD = nfd(stripped);
  const sChars = Array.from(strippedNFD);
  // find vowel groups on stripped
  const sGroups = lastIndexOfGreekVowelGroup(stripped);
  if(sGroups.length<2) return applyAcuteToLastVowel(stripped);
  const sPen = sGroups[sGroups.length-2];
  // insert acute after the first vowel letter of the penult group
  const idx = sPen.start;
  let j = idx+1;
  while(j<sChars.length && /[\u0300-\u036f]/.test(sChars[j])) j++;
  sChars.splice(j,0,acuteComb);
  return nfc(sChars.join(''));
}

function classify(word, opts){
  const original = word.trim();
  if(!original) return {ok:false, msg:'Type a word first.'};

  const normalized = opts.strip ? stripAccentsOnly(original) : original;
  const w = normalized;

  if(!endsWithSos(w)){
    return {ok:false, msg:"This toy expects a disyllabic-looking word ending in -σος."};
  }

  const groups = lastIndexOfGreekVowelGroup(w);
  const syllables = groups.length;
  const pen = groups[groups.length-2];
  const penText = pen ? pen.text.toLowerCase() : '';

  // Determine penult category
  const penCat = (()=>{
    if(!pen) return 'unknown';
    if(pen.type==='diph') return 'diphthong';
    if(penText==='η') return 'eta';
    if(penText==='ω') return 'omega';
    if(penText==='ι' || penText==='υ') return 'i/u';
    return 'other';
  })();

  // Heuristic accent decision
  let decision = 'barytone';
  let why = [];
  let badge = 'good';
  let notes = [];

  if(syllables!==2){
    badge='warn';
    notes.push(`Detected ${syllables} vowel-groups (toy is tuned for disyllables).`);
  }

  if(penCat==='eta'){
    decision='barytone';
    why.push("Penult has η → barytone (Herodian’s rule for -ησος disyllables)." );
    notes.push("Exception mentioned: νῆσος is feminine though most others are masculine (gender not handled)." );
  } else if(penCat==='omega'){
    // passage: feminine -ωσος oxytone; but exceptions Σῶσος, Κρῶσος (masc) barytone
    decision='oxytone';
    why.push("Penult has ω → often oxytone for feminine -ωσος (per passage)." );
    notes.push("But Σῶσος (from σώσω) and Κρῶσος (masc.) are barytone exceptions." );
    badge='warn';
  } else if(penCat==='i/u'){
    decision='barytone';
    why.push("Penult has long ι/υ (often written with circumflex in examples) → barytone for many proper names/monogender nouns." );
    badge='good';
  } else if(penCat==='diphthong'){
    if(opts.cityAdj){
      decision='oxytone';
      why.push("Penult has diphthong and you marked “city/adjective” → oxytone (Παισός-type rule)." );
      badge='good';
    } else {
      decision='oxytone';
      why.push("Penult has diphthong → often oxytone for adjectives/place-names (mark the checkbox if that’s intended)." );
      badge='warn';
    }
  } else {
    decision='barytone';
    why.push("No special penult pattern detected → defaulting to barytone (toy default)." );
    badge='warn';
  }

  // Produce a playful re-accenting
  const reaccented = (decision==='oxytone') ? applyAcuteToLastVowel(w) : applyAcuteToPenultVowel(w);

  return {
    ok:true,
    original,
    used:w,
    syllables,
    penult: pen ? pen.text : '—',
    penCat,
    decision,
    reaccented,
    why,
    notes,
    badge
  };
}

function render(res){
  const out = $('#out');
  if(!res.ok){
    out.innerHTML = `<div class="kv"><div class="k">Message</div><div class="v">${escapeHtml(res.msg)}</div></div>`;
    return;
  }
  const badgeClass = res.badge;
  const badgeText = badgeClass==='good'?'confident-ish':(badgeClass==='warn'?'heuristic':'');

  out.innerHTML = `
    <div class="kv">
      <div class="k">Input</div>
      <div class="v mono">${escapeHtml(res.original)}</div>

      <div class="k">Analyzed as</div>
      <div class="v mono">${escapeHtml(res.used)}</div>

      <div class="k">Penult vowel-group</div>
      <div class="v mono">${escapeHtml(res.penult)} <span class="badge ${badgeClass}">${badgeText}</span></div>

      <div class="k">Toy verdict</div>
      <div class="v"><b>${escapeHtml(res.decision)}</b> (barytone = not final; oxytone = final)</div>

      <div class="k">Toy re-accenting</div>
      <div class="v mono">${escapeHtml(res.reaccented)}</div>

      <div class="k">Reason</div>
      <div class="v">${res.why.map(x=>`<div>• ${escapeHtml(x)}</div>`).join('')}</div>

      <div class="k">Notes</div>
      <div class="v">${(res.notes.length?res.notes.map(x=>`<div>• ${escapeHtml(x)}</div>`).join(''):'—')}</div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[c]));
}

// --- Examples from the passage (and close) ---
const EXAMPLES = [
  {w:'νῆσος', cityAdj:false},
  {w:'Βῆσος', cityAdj:false},
  {w:'Ῥῆσος', cityAdj:false},
  {w:'Κτῆσος', cityAdj:false},
  {w:'Κνωσός', cityAdj:true},
  {w:'Ῥωσός', cityAdj:true},
  {w:'Σῶσος', cityAdj:false},
  {w:'Κρῶσος', cityAdj:false},
  {w:'Νῦσος', cityAdj:false},
  {w:'Τρῦσος', cityAdj:false},
  {w:'Λισός', cityAdj:true},
  {w:'Μυσός', cityAdj:true},
  {w:'χρυσός', cityAdj:false},
  {w:'Παισός', cityAdj:true},
  {w:'Ἀπαισός', cityAdj:true},
  {w:'Πραισός', cityAdj:true},
  {w:'Μαυσός', cityAdj:true},
  {w:'Λουσός', cityAdj:true}
];

function pickExample(){
  return EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];
}

function analyze(){
  const res = classify($('#w').value, {strip: $('#strip').checked, cityAdj: $('#cityAdj').checked});
  render(res);
}

$('#go').addEventListener('click', analyze);
$('#w').addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });
$('#rand').addEventListener('click', ()=>{
  const ex = pickExample();
  $('#w').value = ex.w;
  $('#cityAdj').checked = !!ex.cityAdj;
  analyze();
});

// --- Mini game ---
let current = null;
let selected = null;

const CHOICES = [
  {id:'eta', label:'η (…ησος)'},
  {id:'omega', label:'ω (…ωσος)'},
  {id:'i/u', label:'ι/υ (…ισος/…υσος)'},
  {id:'diphthong', label:'diphthong (αι/ει/οι/…)'},
  {id:'other', label:'other'}
];

function setupChoices(){
  const box = $('#choices');
  box.innerHTML='';
  CHOICES.forEach(c=>{
    const d=document.createElement('div');
    d.className='choice';
    d.textContent=c.label;
    d.dataset.id=c.id;
    d.addEventListener('click', ()=>{
      selected=c.id;
      Array.from(box.children).forEach(x=>x.classList.toggle('sel', x.dataset.id===selected));
      $('#gameMsg').textContent='';
    });
    box.appendChild(d);
  });
}

function newRound(){
  current = pickExample();
  selected = null;
  $('#gameWord').textContent = current.w;
  Array.from($('#choices').children).forEach(x=>x.classList.remove('sel'));
  $('#gameMsg').textContent = 'Pick the penult category, then Reveal.';
}

$('#reveal').addEventListener('click', ()=>{
  if(!current) return;
  const res = classify(current.w, {strip:true, cityAdj: current.cityAdj});
  const correct = res.penCat;
  const msg = [];
  msg.push(`Penult vowel-group: ${res.penult} → category: ${correct}.`);
  msg.push(`Toy verdict: ${res.decision}.`);
  if(selected){
    msg.push(selected===correct ? 'Your pick: correct.' : `Your pick: ${selected} (not this time).`);
  } else {
    msg.push('You did not pick a category.' );
  }
  $('#gameMsg').textContent = msg.join(' ');
});

$('#newRound').addEventListener('click', newRound);

setupChoices();
newRound();

// initial analysis hint
render({ok:false, msg:'Try an example like νῆσος, Κνωσος, Παισος — then click Analyze.'});

