const $ = s=>document.querySelector(s);
const stripDiacritics=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
const key=s=>stripDiacritics(s).toLowerCase();
function lastIndexOfGreekVowelGroup(word){
 const chars=Array.from(key(word)), groups=[];
 const vowels=new Set(Array.from('αεηιουω'));
 const diph=new Set(['αι','ει','οι','υι','αυ','ευ','ου','ηυ','ωυ']);
 for(let i=0;i<chars.length;i++){
  if(!vowels.has(chars[i]))continue;
  const pair=chars[i]+(chars[i+1]||'');
  if(diph.has(pair)){groups.push({text:pair,type:'diph'});i++;}
  else groups.push({text:chars[i],type:'vowel'});
 }
 return groups;
}
const ATTESTED=[];
function add(forms,decision,reason){forms.split(' ').forEach(w=>ATTESTED.push({w,decision,reason}));}
add('νῆσος Βῆσος Μνῆσος Ῥῆσος Κτῆσος Θῆσος Δρῆσος Κῆσος','barytone','η penult: barytone. νῆσος is exceptional in gender, not accent.');
add('κρωσός Κνωσός Ῥωσός','oxytone','The cited feminine disyllables with ω are oxytone. κρωσός is the water-jar.');
add('Σῶσος Κρῶσος','barytone','Named barytone exceptions: Σῶσος from σώσω, and masculine Κρῶσος.');
add('Ἶσος Κῖσος Κρῖσος Πῖσος Νῖσος Νῦσος Τρῦσος κῦσος','barytone','The cited masculine monogender group has long ι or υ in the penult and is barytone.');
add('Λισός Βρυσός Μυσός τρυσός ῥυσός χρυσός','oxytone','Explicit oxytone examples following the long-ι/υ group; do not infer vowel length from spelling.');
add('Παισός Πραισός Μαυσός Λουσός','oxytone','Diphthongal penult: oxytone when adjectival or naming a city; these place examples are cited.');
add('Ἀπαισός','oxytone','Ἀπαισός is explicitly cited as Παισός with added α; it has three vowel groups, outside the disyllabic heading.');
function classify(word,opts){
 const original=word.trim();
 if(!original)return {ok:false,msg:'Type a word first.'};
 const matches=ATTESTED.filter(x=>key(x.w)===key(original));
 if(!matches.length)return {ok:false,msg:'No cited form found. Try νῆσος, Σῶσος, χρυσός or Παισός. No accent is inferred for unlisted words.'};
 const exact=matches.find(x=>x.w.normalize('NFC').toLowerCase()===original.normalize('NFC').toLowerCase());
 if(matches.length>1&&!exact)return {ok:false,msg:'Ambiguous spelling: use κρωσός for the water-jar or Κρῶσος for the masculine name.'};
 const item=exact||matches[0],groups=lastIndexOfGreekVowelGroup(item.w),pen=groups[groups.length-2];
 const penCat=pen.type==='diph'?'diphthong':pen.text==='η'?'eta':pen.text==='ω'?'omega':/[ιυ]/.test(pen.text)?'i/u':'other';
 const notes=[];
 if(penCat==='diphthong'&&opts.cityAdj)notes.push('Condition recalled: adjectival use or a city-name; spelling alone does not establish meaning.');
 if(groups.length!==2)notes.push('This cited expanded form has '+groups.length+' vowel groups.');
 return {ok:true,original,used:opts.strip?stripDiacritics(original):original,syllables:groups.length,penult:pen.text,penCat,decision:item.decision,reaccented:item.w,why:[item.reason],notes,badge:'good'};
}
